function elementBox(el){const content=el.querySelector('.widget-content');return {id:el.dataset.id,x:el.offsetLeft,y:el.offsetTop,w:el.offsetWidth,h:el.offsetHeight,contentW:content?.scrollWidth||0,contentH:content?.scrollHeight||0};}
