function anchorInspector(rule,w,device){return `<details class="responsive-controls" open><summary>Responsive layout · ${device}</summary><p class="hint">Keep a pixel distance from an edge as the canvas changes size. Each device keeps its own rules.</p>${['x','y'].map(axis=>`<label class="field-label">${axis==='x'?'Horizontal anchor':'Vertical anchor'}<select class="field-select" data-anchor="${axis}" ${w.locked?'disabled':''}>${anchorOptions[axis].map(v=>`<option ${rule[axis]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<div class="property-grid">${['offsetX','offsetY'].map(k=>`<label>${k==='offsetX'?'Horizontal gap':'Vertical gap'} (px)<input type="number" step="1" min="-2000" max="2000" data-anchor="${k}" value="${Math.round(rule[k])}" ${w.locked?'disabled':''}></label>`).join('')}</div><label class="input-row">Keep size in pixels<input type="checkbox" data-anchor="fixed" ${rule.fixed?'checked':''} ${w.locked?'disabled':''}></label></details>`;}
function changeAnchor(el){if(state.widgets[selected].locked)return;try{const k=el.dataset.anchor,rule={...state.constraints[state.device][selected]};rule[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;const box=elementBox(stage.querySelector(`[data-id=${selected}]`));state.constraints[state.device][selected]=['x','y','fixed'].includes(k)?captureConstraint(rule,box,stage.clientWidth,stage.clientHeight):validateConstraint(rule);if(['x','y','fixed'].includes(k))Object.assign(state.widgets[selected],{x:box.x/stage.clientWidth*100,y:box.y/stage.clientHeight*100,w:box.w/stage.clientWidth*100,h:box.h/stage.clientHeight*100});commit();}catch(err){notify(err.message);renderInspector();}}
function arrangeSelection(mode,axis){const ids=[...selection].filter(id=>screenWidgets(state).includes(id)),next=clone(state);try{for(const id of ids){const el=stage.querySelector(`[data-id=${id}]`);if(el){const b=elementBox(el);Object.assign(next.widgets[id],{x:b.x/stage.clientWidth*100,y:b.y/stage.clientHeight*100,w:b.w/stage.clientWidth*100,h:b.h/stage.clientHeight*100});}}arrangeWidgets(next,ids,mode,axis);state=next;captureAnchors(ids);commit();}catch(err){notify(err.message);}}
