function setSetting(field,value){if(field==='navigation')for(const id of ['shop','map','board','calendar']){setButton(state,id,'display',value==='compact'?'icon':'both');setButton(state,id,'orientation',value==='rail'?'vertical':'horizontal');}if(field==='device')switchDevice(state,value);else state[field]=value;if(field==='screen'){drawer=false;chat=false;line=0;selected=state.screen==='choice_hub'?'choices':state.screen==='dialogue'?'dialogue':'panel';selection.clear();selection.add(selected);}commit();}
