stage.addEventListener('pointerdown',e=>{
  if(playing||e.button!==0)return;const el=e.target.closest('.game-widget');if(!el){selected=null;selection.clear();renderInspector();stage.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));return;}
  if(e.shiftKey){const id=el.dataset.id;if(selection.has(id))selection.delete(id);else selection.add(id);selected=selection.has(id)?id:[...selection].at(-1)||null;render();return;}if(!selection.has(el.dataset.id)){selection.clear();selection.add(el.dataset.id);}selected=el.dataset.id;stage.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');renderInspector();
  const w=state.widgets[selected];if(w.locked||e.target.closest('input,select,textarea')||(!state.buttons[selected]&&e.target.closest('button')))return;
  e.preventDefault();const rect=stage.getBoundingClientRect(),start={...clone(w),x:el.offsetLeft/rect.width*100,y:el.offsetTop/rect.height*100,w:el.offsetWidth/rect.width*100,h:el.offsetHeight/rect.height*100};drag={id:selected,el,pointer:e.pointerId,resize:!!e.target.closest('[data-resize]'),clientX:e.clientX,clientY:e.clientY,rect,start,before:clone(w),beforeConstraint:clone(state.constraints[state.device][selected])};stage.setPointerCapture(e.pointerId);
});
stage.addEventListener('focusin',e=>{if(playing)return;const el=e.target.closest('.game-widget');if(el&&selected!==el.dataset.id){selected=el.dataset.id;stage.querySelectorAll('.selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');renderInspector();}});
stage.addEventListener('pointermove',e=>{
  if(!drag||e.pointerId!==drag.pointer)return;const w=state.widgets[drag.id],dx=(e.clientX-drag.clientX)/drag.rect.width*100,dy=(e.clientY-drag.clientY)/drag.rect.height*100;
  const snap=n=>state.snap?Math.round(n/2)*2:n;
  Object.assign(w,{x:drag.start.x,y:drag.start.y,w:drag.start.w,h:drag.start.h});
  if(drag.resize)resizeWidget(w,snap(drag.start.w+dx),snap(drag.start.h+dy));else moveWidget(w,snap(drag.start.x+dx),snap(drag.start.y+dy));
  Object.assign(drag.el.style,{left:w.x+'%',top:w.y+'%',width:w.w+'%',height:w.h+'%'});
  stage.querySelectorAll('.snap-guide').forEach(el=>el.remove());if(!drag.resize)smartGuides(drag.el,w);updateWarnings();
});
function finishDrag(e){if(!drag||e.pointerId!==drag.pointer)return;const id=drag.pointer;if(!drag.cancelled)captureAnchors([drag.id],true);drag=null;if(stage.hasPointerCapture(id))stage.releasePointerCapture(id);commit();}
stage.addEventListener('pointerup',finishDrag);stage.addEventListener('pointercancel',e=>{if(drag){state.widgets[drag.id]=drag.before;state.constraints[state.device][drag.id]=drag.beforeConstraint;drag.cancelled=true;finishDrag(e);}});stage.addEventListener('lostpointercapture',e=>{if(drag)finishDrag(e);});
function feedback(text){stage.querySelector('.play-feedback')?.remove();const el=document.createElement('div');el.className='play-feedback';el.setAttribute('role','status');el.textContent=text;stage.append(el);setTimeout(()=>el.remove(),2600);}
stage.addEventListener('click',e=>{
  const btn=e.target.closest('button');if(!btn)return;
  if(btn.dataset.tool){utilityTarget=btn.dataset.tool;if(playing){utilityOpen=utilityTarget;renderStage();stage.querySelector('[data-close-utility]').focus();}else{selected='tool_'+utilityTarget;renderInspector();}return;}
  if(btn.hasAttribute('data-close-utility')){utilityOpen=null;renderStage();stage.querySelector(`[data-tool=${utilityTarget}]`)?.focus();return;}
  if(btn.dataset.previewSlot){if(btn.dataset.previewSlot==='save')previewSlot={screen:state.screen,line};else if(previewSlot){state.screen=previewSlot.screen;line=previewSlot.line;save();}renderStage();stage.querySelector('[data-close-utility]')?.focus();return;}
  if(!playing){notify('Switch to Play preview to try the controls.');return;}
  if(btn.dataset.navigate){utilityOpen=null;setSetting('screen',btn.dataset.navigate);return;}
  if(btn.dataset.playChoice!==undefined){feedback('Selected: '+btn.querySelector('.choice-text').textContent+' · simulated');return;}
  const demo=btn.dataset.demo;
  if(demo==='drawer'){drawer=true;renderStage();stage.querySelector('input')?.focus();}
  else if(demo==='chat'){chat=!chat;renderStage();}
  else if(demo==='advance'){line=(line+1)%3;renderStage();}
  else if(demo==='cancel'||demo==='retry'){state.sample='normal';commit();feedback(demo==='retry'?'Retry simulated. Ready for another response.':'Waiting cancelled.');}
  else if(demo==='music'){btn.textContent=btn.textContent.startsWith('▶')?'Ⅱ Simulated playback active':'▶ Simulate playback';feedback('Playback state preview · no audio file connected');}
  else if(demo){btn.classList.toggle('selected-item');feedback(btn.textContent.trim()+' · preview selection');}
});
stage.addEventListener('submit',e=>{e.preventDefault();if(!playing){notify('Switch to Play preview to submit a sample response.');return;}const input=e.target.querySelector('input');if(input?.value.trim()){feedback('Response received locally: '+input.value.trim());input.value='';}});
document.addEventListener('keydown',e=>{
  if(utilityOpen){if(e.key==='Escape'){e.preventDefault();utilityOpen=null;renderStage();stage.querySelector(`[data-tool=${utilityTarget}]`)?.focus();return;}if(e.key==='Tab'){const nodes=[...stage.querySelectorAll('.utility-modal button:not(:disabled),.utility-modal input')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}
  if(e.target.closest('input,textarea,select')||drag||section==='assets')return;
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();state=e.shiftKey?hist.redo():hist.undo();save();render();return;}
  if(e.key==='Escape'){selected=null;selection.clear();render();return;}
  if(!playing&&selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const w=state.widgets[selected];if(w.locked)return;e.preventDefault();const el=stage.querySelector(`[data-id=${selected}]`);if(el){const box=elementBox(el);Object.assign(w,{x:box.x/stage.clientWidth*100,y:box.y/stage.clientHeight*100,w:box.w/stage.clientWidth*100,h:box.h/stage.clientHeight*100});}const d=e.shiftKey?2:.5;moveWidget(w,w.x+(e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0),w.y+(e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0));captureAnchors([selected]);commit();stage.focus();}
});
render();if(!storageOK)$('saveStatus').textContent='Export to keep your work';
